#!/usr/bin/env python3
# Some portions generated by Codex
"""Deterministic contracts for the selector's prior-fitting arithmetic."""

import contextlib
import importlib.util
import io
import tempfile
import unittest
from pathlib import Path


SCRIPT = Path(__file__).with_name("lmdb-fit-prior.py")
SPEC = importlib.util.spec_from_file_location("lmdb_fit_prior", SCRIPT)
FIT = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(FIT)


class LmdbFitPriorTest(unittest.TestCase):

    def test_constant_single_feature_converges_without_oscillation(self):
        rows = [([1.0], 10.0, None), ([1.0], 10.0, None)]
        self.assertAlmostEqual(FIT.nnls(rows, 1)[0], 10.0, places=6)

    def test_identical_features_predict_the_target_without_oscillation(self):
        rows = [([1.0, 1.0], 10.0, None)]
        coefficients = FIT.nnls(rows, 2)
        self.assertAlmostEqual(sum(coefficients), 10.0, places=6)
        self.assertTrue(all(coefficient >= 0.0 for coefficient in coefficients))

    def test_fully_pinned_model_has_no_free_coefficients(self):
        # main() legitimately produces this reduced problem when every feature is pinned.
        self.assertEqual(FIT.nnls([([], 10.0, None)], 0), [])

    def test_different_feature_scales_recover_exact_slopes(self):
        rows = [([1.0, 0.0], 3.0, None), ([0.0, 1000.0], 20.0, None)]
        coefficients = FIT.nnls(rows, 2)
        self.assertAlmostEqual(coefficients[0], 3.0, places=6)
        self.assertAlmostEqual(coefficients[1], 0.02, places=6)

    def test_negative_targets_do_not_create_negative_coefficients(self):
        self.assertEqual(FIT.nnls([([1.0], -10.0, None)], 1), [0.0])

    def test_unobserved_feature_stays_zero(self):
        coefficients = FIT.nnls([([1.0, 0.0], 10.0, None)], 2)
        self.assertAlmostEqual(coefficients[0], 10.0, places=6)
        self.assertEqual(coefficients[1], 0.0)


class LmdbFitPriorInputTest(unittest.TestCase):

    def setUp(self):
        self.temporary = tempfile.TemporaryDirectory()
        self.addCleanup(self.temporary.cleanup)
        self.directory = Path(self.temporary.name)

    def write_measurements(self, name, features, rows):
        path = self.directory / name
        header = "# query\tindexes\tadjacency\tpoint\tstrategy\tchosen\tmedianNanos\tminNanos\trows"
        header += "\texpectedNanos\tlowNanos\thighNanos\tnote\tfeatures(" + ",".join(features) + ")\n"
        lines = []
        for values, nanos in rows:
            cells = ["query", "spoc", "lmdbOnly", "row/join dispatch", "nestedLoop", "chosen",
                     str(nanos), str(nanos), "1", "0", "0", "0", "", ",".join(map(str, values))]
            lines.append("\t".join(cells))
        path.write_text(header + "\n".join(lines) + "\n", encoding="utf-8")
        return path

    def test_pinned_overprediction_keeps_negative_residual_in_objective(self):
        path = self.write_measurements("pinned.tsv", ["OPEN", "SCANNED_ROW"],
                                       [([20.0, 1.0], 10.0), ([0.0, 1.0], 10.0)])
        output = io.StringIO()
        with contextlib.redirect_stdout(output):
            status = FIT.main([str(path), "--pin", "OPEN=1"])
        self.assertEqual(status, 0)
        # Residual targets are -10 and +10. Their constrained least-squares slope is zero,
        # not five: clipping the negative residual would silently change the fitted objective.
        line = next(line for line in output.getvalue().splitlines() if line.startswith("SCANNED_ROW"))
        self.assertAlmostEqual(float(line.split()[2]), 0.0, places=6)

    def test_multiple_files_with_reordered_features_are_rejected(self):
        first = self.write_measurements("first.tsv", ["OPEN", "SCANNED_ROW"], [([1.0, 2.0], 10.0)])
        second = self.write_measurements("second.tsv", ["SCANNED_ROW", "OPEN"], [([2.0, 1.0], 10.0)])
        with self.assertRaisesRegex(ValueError, "[Ff]eature.*schema"):
            FIT.load([str(first), str(second)])

    def test_multiple_files_with_different_feature_counts_are_rejected(self):
        first = self.write_measurements("first.tsv", ["OPEN"], [([1.0], 10.0)])
        second = self.write_measurements("second.tsv", ["OPEN", "SCANNED_ROW"], [([1.0, 2.0], 10.0)])
        with self.assertRaisesRegex(ValueError, "[Ff]eature.*schema"):
            FIT.load([str(first), str(second)])

    def test_feature_vector_length_must_match_its_header(self):
        path = self.write_measurements("short.tsv", ["OPEN", "SCANNED_ROW"], [([1.0], 10.0)])
        with self.assertRaisesRegex(ValueError, "[Ff]eature.*(count|length)"):
            FIT.load([str(path)])

    def test_every_file_requires_a_feature_header(self):
        first = self.write_measurements("first.tsv", ["OPEN"], [([1.0], 10.0)])
        second = self.directory / "no-header.tsv"
        second.write_text(first.read_text(encoding="utf-8").splitlines()[1] + "\n", encoding="utf-8")
        with self.assertRaisesRegex(ValueError, "[Ff]eature.*header"):
            FIT.load([str(first), str(second)])

    def test_unbounded_quote_is_not_fit_when_expected_features_are_finite(self):
        path = self.write_measurements("unbounded.tsv", ["SCANNED_ROW"], [([0.0], 10.0)])
        lines = path.read_text(encoding="utf-8").splitlines()
        cells = lines[1].split("\t")
        cells[11] = "Infinity"
        path.write_text(lines[0] + "\n" + "\t".join(cells) + "\n", encoding="utf-8")
        names, rows = FIT.load([str(path)])
        self.assertEqual(names, ["SCANNED_ROW"])
        self.assertEqual(rows, [], "The expected feature floor cannot establish that a quote is bounded")

    def test_finite_large_quote_is_not_mistaken_for_an_unbounded_quote(self):
        path = self.write_measurements("large.tsv", ["SCANNED_ROW"], [([1e14], 10.0)])
        lines = path.read_text(encoding="utf-8").splitlines()
        cells = lines[1].split("\t")
        cells[11] = "100000000000000"
        path.write_text(lines[0] + "\n" + "\t".join(cells) + "\n", encoding="utf-8")
        _, rows = FIT.load([str(path)])
        self.assertEqual(len(rows), 1)

    def test_compatible_files_preserve_all_measurements(self):
        first = self.write_measurements("first.tsv", ["OPEN", "SCANNED_ROW"], [([1.0, 2.0], 10.0)])
        second = self.write_measurements("second.tsv", ["OPEN", "SCANNED_ROW"], [([3.0, 4.0], 20.0)])
        names, rows = FIT.load([str(first), str(second)])
        self.assertEqual(names, ["OPEN", "SCANNED_ROW"])
        self.assertEqual([row[0] for row in rows], [[1.0, 2.0], [3.0, 4.0]])
        self.assertEqual([row[1] for row in rows], [10.0, 20.0])

    def test_censored_or_nonfinite_elapsed_measurements_do_not_enter_the_fit(self):
        for elapsed in (float("inf"), float("-inf"), float("nan")):
            with self.subTest(elapsed=elapsed):
                path = self.write_measurements("censored.tsv", ["OPEN"], [([1.0], elapsed)])
                names, rows = FIT.load([str(path)])
                self.assertEqual(names, ["OPEN"])
                self.assertEqual(rows, [], "A censored run cannot be treated as an exact elapsed target")

    def test_negative_elapsed_measurement_is_rejected(self):
        path = self.write_measurements("negative-time.tsv", ["OPEN"], [([1.0], -1.0)])
        with self.assertRaisesRegex(ValueError, "[Ee]lapsed.*negative-time.tsv:2"):
            FIT.load([str(path)])

    def test_nonfinite_or_negative_feature_counts_are_rejected(self):
        for count in (float("nan"), float("inf"), float("-inf"), -1.0):
            with self.subTest(count=count):
                path = self.write_measurements("invalid-count.tsv", ["OPEN"], [([count], 10.0)])
                with self.assertRaisesRegex(ValueError, "[Ff]eature.*invalid-count.tsv:2"):
                    FIT.load([str(path)])

    def test_duplicate_or_empty_feature_names_are_rejected(self):
        for names in (["OPEN", "OPEN"], ["OPEN", ""]):
            with self.subTest(names=names):
                path = self.write_measurements("invalid-schema.tsv", names, [([1.0, 2.0], 10.0)])
                with self.assertRaisesRegex(ValueError, "[Ff]eature.*invalid-schema.tsv:1"):
                    FIT.load([str(path)])

    def test_invalid_pinned_coefficients_are_rejected(self):
        path = self.write_measurements("pins.tsv", ["OPEN"], [([1.0], 10.0)])
        for pin in ("OPEN=NaN", "OPEN=Infinity", "OPEN=-1", "MISSPELLED=1"):
            with self.subTest(pin=pin):
                with self.assertRaisesRegex(ValueError, "[Pp]in"):
                    FIT.main([str(path), "--pin", pin])


if __name__ == "__main__":
    unittest.main()
